## Mini Chess Board

### Piece Model

```xiom
enum PieceColor {
  White;
  Black;
}

enum PieceType {
  King;
  Queen;
  Rook;
  Bishop;
  Knight;
  Pawn;
  Empty;
}

type Square {
  piece: PieceType;
  color: PieceColor;
}

type ChessBoard {
  squares: Vec[Vec[Square]];
}
```

### Piece Symbols

```xiom
fn piece_symbol(piece: PieceType, color: PieceColor) -> Str {
  let symbols: Vec<(PieceType, Str, Str)> = Vec<(PieceType, Str, Str)>.new();
  symbols.push((PieceType.King, "K", "k"));
  symbols.push((PieceType.Queen, "Q", "q"));
  symbols.push((PieceType.Rook, "R", "r"));
  symbols.push((PieceType.Bishop, "B", "b"));
  symbols.push((PieceType.Knight, "N", "n"));
  symbols.push((PieceType.Pawn, "P", "p"));

  let mut i = 0;
  while i < symbols.len() {
    let s = symbols.get(i).unwrap();
    if s.0 == piece {
      return if color == PieceColor.White { s.1 } else { s.2 };
    };
    i += 1;
  };
  "."
}
```

### Setting Up the Board

```xiom
fn setup_board() -> ChessBoard {
  let empty_sq = Square{ piece: PieceType.Empty, color: PieceColor.White };
  let mut squares: Vec[Vec[Square]] = Vec[Vec[Square]].new();

  let back_rank: Vec<PieceType> = Vec[PieceType].new();
  back_rank.push(PieceType.Rook); back_rank.push(PieceType.Knight);
  back_rank.push(PieceType.Bishop); back_rank.push(PieceType.Queen);
  back_rank.push(PieceType.King); back_rank.push(PieceType.Bishop);
  back_rank.push(PieceType.Knight); back_rank.push(PieceType.Rook);

  let mut r = 0;
  while r < 8 {
    let mut row: Vec[Square] = Vec[Square].new();
    let mut c = 0;
    while c < 8 {
      if r == 0 {
        row.push(Square{ piece: back_rank.get(c).unwrap(), color: PieceColor.Black });
      } else if r == 1 {
        row.push(Square{ piece: PieceType.Pawn, color: PieceColor.Black });
      } else if r == 6 {
        row.push(Square{ piece: PieceType.Pawn, color: PieceColor.White });
      } else if r == 7 {
        row.push(Square{ piece: back_rank.get(c).unwrap(), color: PieceColor.White });
      } else {
        row.push(empty_sq);
      };
      c += 1;
    };
    squares.push(row);
    r += 1;
  };
  ChessBoard{ squares: squares }
}
```

### Displaying the Board

```xiom
fn display_board(board: &ChessBoard) {
  let mut r = 0;
  while r < 8 {
    let mut line: Str = "";
    let rank = 8 - r;
    line = line + rank;
    line = line + " ";
    let mut c = 0;
    while c < 8 {
      let sq = board.squares.get(r).unwrap().get(c).unwrap();
      line = line + piece_symbol(sq.piece, sq.color) + " ";
      c += 1;
    };
    io.println(line);
    r += 1;
  };
  io.println("  a b c d e f g h");
}
```

### Basic Pawn Movement

```xiom
fn pawn_moves(board: &ChessBoard, row: Int, col: Int, color: PieceColor) -> Vec<(Int, Int)> {
  let mut moves: Vec<(Int, Int)> = Vec<(Int, Int)>.new();
  let dir = if color == PieceColor.White { -1 } else { 1 };
  let start_row = if color == PieceColor.White { 6 } else { 1 };

  let new_row = row + dir;
  if new_row >= 0 && new_row < 8 {
    let target = board.squares.get(new_row).unwrap().get(col).unwrap();
    if target.piece == PieceType.Empty {
      moves.push((new_row, col));

      if row == start_row {
        let double_row = row + dir * 2;
        let double_target = board.squares.get(double_row).unwrap().get(col).unwrap();
        if double_target.piece == PieceType.Empty {
          moves.push((double_row, col));
        };
      };
    };
  };
  moves
}
