use xiom.io;
enum Piece {
  Empty;
  Pawn;
  Rook;
  Knight;
  Bishop;
  Queen;
  King;
}

type GameBoard {
  grid: Vec[Vec[Piece]];
}

fn create_board() -> GameBoard {
  let back: Vec[Piece] = Vec[Piece].new();
  back.push(Piece.Rook); back.push(Piece.Knight); back.push(Piece.Bishop);
  back.push(Piece.Queen); back.push(Piece.King);
  back.push(Piece.Bishop); back.push(Piece.Knight); back.push(Piece.Rook);

  let mut grid: Vec[Vec[Piece]] = Vec[Vec[Piece]].new();
  let mut r = 0;
  while r < 8 {
    let mut row: Vec[Piece] = Vec[Piece].new();
    let mut c = 0;
    while c < 8 {
      if r == 0 {
        row.push(back.get(c).unwrap());
      } else if r == 1 {
        row.push(Piece.Pawn);
      } else if r == 6 {
        row.push(Piece.Pawn);
      } else if r == 7 {
        row.push(back.get(c).unwrap());
      } else {
        row.push(Piece.Empty);
      };
      c = c + 1;
    };
    grid.push(row);
    r = r + 1;
  };
  GameBoard{ grid: grid }
}

fn piece_char(p: Piece) -> Str {
  match p {
    Piece.Empty => ".",
    Piece.Pawn => "P",
    Piece.Rook => "R",
    Piece.Knight => "N",
    Piece.Bishop => "B",
    Piece.Queen => "Q",
    Piece.King => "K",
  }
}

fn display(board: &GameBoard) {
  io.println("  a b c d e f g h");
  let mut r = 0;
  while r < 8 {
    let mut line: Str = "";
    let rank = 8 - r;
    line = line + rank;
    line = line + " ";
    let mut c = 0;
    while c < 8 {
      line = line + piece_char(board.grid.get(r).unwrap().get(c).unwrap()) + " ";
      c = c + 1;
    };
    io.println(line.to_str());
    r = r + 1;
  };
}

fn main() -> Int {
  let board = create_board();
  display(&board);
  return 0;
}
